"""A step goes on to its next step OR ends the flow, never both.

Connecting a step that was wired to END to another step kept its END link, so
the runtime stopped there and the next step never ran. The next step wins: the
END link is cleared, and moves to the next step when that one was the last.
"""

from django.db import migrations


def repair(apps, schema_editor):
    Step = apps.get_model("agents", "Step")
    live = Step.objects.filter(is_deleted=False)
    for step in live.filter(connected_to_end=True, next_step__isnull=False):
        nxt = live.filter(pk=step.next_step_id, agent_id=step.agent_id).first()
        if nxt is None:
            continue
        step.connected_to_end = False
        step.save(update_fields=["connected_to_end"])
        if nxt.next_step_id is None and not nxt.connected_to_end:
            nxt.connected_to_end = True
            nxt.save(update_fields=["connected_to_end"])


